@bp.route('/low-stock', methods=['GET'])
def get_low_stock_products():
    """Obtiene productos con stock bajo según el umbral especificado"""
    try:
        threshold = request.args.get('threshold', default=10, type=int)

        if threshold < 0:
            return error_response('El umbral no puede ser negativo', 400)

        # Obtener productos con stock <= umbral
        products = Product.query.filter(Product.stock <= threshold).order_by(Product.stock.asc()).all()

        # Calcular restock_value para cada producto
        result = []
        for product in products:
            product_dict = product.to_dict()
            product_dict['restock_value'] = (threshold - product_dict['stock']) * product_dict['price']
            result.append(product_dict)

        return success_response(
            data=result,
            count=len(result)
        )
    except ValueError:
        return error_response('El umbral debe ser un número entero', 400)
    except Exception as e:
        return error_response(f'Error al obtener productos con stock bajo: {str(e)}', 500)
